export const NOW = Date.UTC(2026, 9, 26, 9, 0)

/* ---------- model.ts date helpers, in UTC ---------- */

const startOfDay = (ms: number) => {
  const date = new Date(ms)
  return Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate())
}
const addDays = (ms: number, days: number) => {
  const date = new Date(ms)
  date.setUTCDate(date.getUTCDate() + days)
  return date.getTime()
}
const addMonths = (ms: number, months: number) => {
  const date = new Date(ms)
  const day = date.getUTCDate()
  date.setUTCDate(1)
  date.setUTCMonth(date.getUTCMonth() + months)
  const last = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 0)).getUTCDate()
  date.setUTCDate(Math.min(day, last))
  return date.getTime()
}
const withTime = (ms: number, hours: number, minutes: number) => {
  const date = new Date(ms)
  date.setUTCHours(hours, minutes, 0, 0)
  return date.getTime()
}
const weekdayOf = (ms: number) => new Date(ms).getUTCDay()

export const TASK_RECURRENCES = ['none', 'daily', 'weekdays', 'weekly', 'monthly', 'yearly'] as const
export type Recurrence = (typeof TASK_RECURRENCES)[number]
