export const SAVED = { ...parseQuickAdd(`${PAGE.title} tomorrow @reading`), saved: true }

export const LIST = [
  HERO,
  parseQuickAdd('Water the plants every monday'),
  parseQuickAdd('Call the bank this afternoon p3'),
  parseQuickAdd('Book the dentist wed #Home'),
  parseQuickAdd('Renew the passport in 2 weeks p2 #Home'),
]
const ALL = [...LIST, TYPED, SAVED]

function views() {
  const today = startOfDay(NOW)
  const dated = ALL.filter((task) => task.due != null)
  const isToday = (task: Parsed) => startOfDay(task.due!) === today
  const upcoming = dated
    .filter((task) => task.due! < addDays(today, UPCOMING_DAYS))
    .sort((a, b) => a.due! - b.due!)
  const days = new Map<number, Parsed[]>()
  for (const task of upcoming) {
    const key = startOfDay(task.due!)
    days.set(key, [...(days.get(key) ?? []), task])
  }
  return {
    today: dated.filter(isToday),
    upcoming: [...days].map(([day, tasks]) => ({ label: formatDay(day), tasks })),
    inbox: ALL.filter((task) => task.project == null),
  }
}
export const VIEWS = views()

/** The two-week grid the Upcoming view covers, with how many sample tasks fall on each day. */
export const FORTNIGHT = Array.from({ length: UPCOMING_DAYS }, (_, index) => {
  const day = addDays(startOfDay(NOW), index)
  return {
    date: new Date(day).getUTCDate(),
    weekday: new Intl.DateTimeFormat('en-US', { weekday: 'narrow', timeZone: 'UTC' }).format(day),
    load: ALL.filter((task) => task.due != null && startOfDay(task.due) === day).length,
  }
})

